<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> promise3 </span><span style="color:#89DDFF;">=</span><span style="color:#FFCB6B;"> Promise</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">resolve</span><span style="color:#BABED8;">(</span><span style="color:#F78C6C;">3</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
